-- S16: 6 candidatas, 48 vectores, sin juicio ni promoción.
BEGIN;
DO $s16$
DECLARE p jsonb; q jsonb; e jsonb; cd text; lid int; n int:=0; b_leg jsonb; b_bridge jsonb; b_pub jsonb; b_dep jsonb; b_judge jsonb; b_cand int;
