 SELECT count(*) INTO b_cand FROM lf_ops.nucleo_regla_versiones WHERE estado='CANDIDATA';
 IF EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla LIKE 'S16-C%') THEN RAISE EXCEPTION 'S16_CANDIDATES_ALREADY_EXIST'; END IF;
