no_no_autorizado":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s16c04_b2b_autenticado":false,"s16c04_redireccion":true,"s16c04_destino_no_autorizado":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s16c04_b2b_autenticado":false,"s16c04_redireccion":true,"s16c04_destino_no_autorizado":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s16c04_b2b_autenticado":true,"s16c04_redireccion":false,"s16c04_destino_no_autorizado":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s16c04_b2b_autenticado":true,"s16c04_redireccion":false,"s16c04_destino_no_autorizado":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s16c04_b2b_autenticado":true,"s16c04_redireccion":true,"s16c04_destino_no_autorizado":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s16c04_b2b_autenticado":true,"s16c04_redireccion":true,"s16c04_destino_no_autorizado":true},"esperado":true}],"efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/442","solicitante":"Cristhian / Claude S16 2026-11-24"}},{"tipo":"NUEVA","codigo":"S16-C05","clave":"s16_reg_client_home_active_offer_variant_001","familia":"UI_MESSAGES","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_HOME","modo":"HEREDA","dueno":"TECNICO","titulo":"Cuenta regresiva de oferta web","descripcion":"BLOQUEAR countdown web de oferta activa que muestre segundos o unidades agotadas; proyectar días, horas y minutos restantes según vigencia autoritativa, sin redefinir selección ni modalidades.","condicion":{"op":"y","izq":{"op":"y","izq":{"op":"=","izq":{"hecho":"s16c05_oferta_activa_web"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s16c05_countdown_visible"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s16c05_unidad_temporal_invalida"},"der":{"lit":true}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s16c05_oferta_activa_web":false,"s16c05_countdown_visible":false,"s16c05_unidad_temporal_invalida":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s16c05_oferta_activa_web":false,"s16c05_countdown_visible":false,"s16c05_unidad_temporal_invalida":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s16c05_oferta_activa_web":false,"s16c05_countdown_visible":true,"s16c05_unidad_temporal_invalida":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s16c05_oferta_activa_web":false,"s16c05_countdown_visible":true,"s16c05_unidad_temporal_invalida":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s16c05_oferta_activa_web":true,"s16c05_countdown_visible":false,"s16c05_unidad_temporal_invalida":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s16c05_oferta_activa_web":true,"s16c05_countdown_visible":false,"s16c05_unidad_temporal_invalida":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s16c05_oferta_activa_web":true,"s16c05_countdown_visible":true,"s16c05_unidad_temporal_invalida":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s16c05_oferta_activa_web":true,"s16c05_countdown_visible":true,"s16c05_unidad_temporal_invalida":true},"esperado":true}],"efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/517","solicitante":"Cristhian / Claude S16 2026-11-24"}},{"tipo":"NUEVA","codigo":"S16-C06","clave":"s16_neg_respaldo_sin_cajas_vacias_01","familia":"B2B_PARTNERS","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_HOME","modo":"HEREDA","dueno":"TECNICO","titulo":"Aliados y prensa visibles autorizados","descripcion":"BLOQUEAR Home público que muestre aliado sin aprobación y visibilidad, noticia sin verificación y visibilidad, o slot futuro fuera de sandbox/pitch interno.","condicion":{"op":"y","izq":{"op":"y","izq":{"op":"=","izq":{"hecho":"s16c06_home_publico"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s16c06_aliado_o_prensa_renderizado"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s16c06_visibilidad_no_autorizada"},"der":{"lit":true}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s16c06_home_publico":false,"s16c06_aliado_o_prensa_renderizado":false,"s16c06_visibilidad_no_autorizada":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s16c06_home_publico":false,"s16c06_aliado_o_prensa_renderizado":false,"s16c06_visibilidad_no_autorizada":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s16c06_home_publico":false,"s16c06_aliado_o_prensa_renderizado":true,"s16c06_visibilidad_no_autorizada":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s16c06_home_publico":false,"s16c06_aliado_o_prensa_renderizado":true,"s16c06_visibilidad_no_autorizada":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s16c06_home_publico":true,"s16c06_aliado_o_prensa_renderizado":false,"s16c06_visibilidad_no_autorizada":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s16c06_home_publico":true,"s16c06_aliado_o_prensa_renderizado":false,"s16c06_visibilidad_no_autorizada":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s16c06_home_publico":true,"s16c06_aliado_o_prensa_renderizado":true,"s16c06_visibilidad_no_autorizada":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s16c06_home_publico":true,"s16c06_aliado_o_prensa_renderizado":true,"s16c06_visibilidad_no_autorizada":true},"esperado":true}],"efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/368","solicitante":"Cristhian / Claude S16 2026-11-24"}}]$packets$::jsonb) LOOP
 cd:=p->>'codigo'; lid:=substring(p->'origen'->>'ref' from '[0-9]+$')::int;
 IF (SELECT count(*) FROM lf_ops.reglas)=586 AND NOT EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid AND estado='VIGENTE' AND NOT coalesce(pendiente_decision,false)) THEN RAISE EXCEPTION 'S16_SOURCE_NOT_ELIGIBLE %',lid; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada WHERE legacy_id=lid AND estado_cobertura='REEMPLAZADA') THEN RAISE EXCEPTION 'S16_ALREADY_COVERED %',lid; END IF;
 q:=lf_ops.nucleo_regla_proponer_v1(p,false);
 IF q->>'resultado'<>'EVALUADA_SIN_ESCRIBIR' OR (q->>'bloqueantes')::int<>0 THEN RAISE EXCEPTION 'S16_PREFLIGHT_FAIL % %',cd,q; END IF;
 q:=lf_ops.nucleo_regla_proponer_v1(p,true);
 IF q->>'resultado'<>'CANDIDATA' OR (q->>'version')::int<>1 THEN RAISE EXCEPTION 'S16_CREATE_FAIL % %',cd,q; END IF;
 IF (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8 OR (SELECT count(distinct entrada::text) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8 THEN RAISE EXCEPTION 'S16_VECTOR_INVALID %',cd; END IF;
 e:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF e->>'decision'<>'BLOQUEADA' OR e->>'hash_paquete' IS NULL THEN RAISE EXCEPTION 'S16_GATE_FAIL % %',cd,e; END IF;
 n:=n+1; RAISE NOTICE 'S16_CANDIDATE % hash=%',cd,e->>'hash_paquete';
 END LOOP;
 IF n<>6 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE estado='CANDIDATA')<>b_cand+6 OR (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla LIKE 'S16-C%')<>48
 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM lf_ops.reglas t) IS DISTINCT FROM b_leg
 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY legacy_id,nucleo_codigo,version_nucleo) FROM lf_ops.lf_nucleo_cobertura_legada t) IS DISTINCT FROM b_bridge
 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) FROM lf_ops.nucleo_regla_versiones t WHERE estado='PUBLICADA') IS DISTINCT FROM b_pub
 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones t) IS DISTINCT FROM b_dep
 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM lf_ops.nucleo_juicios t) IS DISTINCT FROM b_judge THEN RAISE EXCEPTION 'S16_CONSERVATION_FAIL'; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.pantallas WHERE id=36) AND jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S16_DPIG03_FAIL'; END IF;
 RAISE NOTICE 'S16_PASS 6 CANDIDATAS 48 VECTORES 0 PROMOCIONES';
END $s16$;
COMMIT;
